use rk3588_boot_support::Mmio32;use rk3588_boot_support::stage16::EarlyClockReset;use crate::stage14::EntryCpuIo;use crate::stage15::EarlyPinOp;
#[derive(Clone,Copy,Debug,PartialEq,Eq)]pub enum EarlyStartupError<E>{ClockReset(E),Pinctrl(crate::stage12::PinctrlError)}
/// Reconstructed composition boundary only: exact CRU programming remains in
/// `EarlyClockReset` until binary-derived clock/reset writes are frozen.
pub fn run_early_startup<C:EntryCpuIo,M:Mmio32,H:EarlyClockReset>(cpu:&mut C,mmio:&mut M,clock_reset:&mut H,current_el:u64,timer_hz:u64,grf_base:u64,pins:&[EarlyPinOp])->Result<(),EarlyStartupError<H::Error>>{crate::stage14::apply_entry_cpu_state(cpu,current_el,timer_hz);clock_reset.prepare_clocks().map_err(EarlyStartupError::ClockReset)?;crate::stage15::apply_early_pin_ops(mmio,grf_base,pins).map_err(EarlyStartupError::Pinctrl)?;clock_reset.release_resets().map_err(EarlyStartupError::ClockReset)}
#[cfg(test)]mod tests{use super::*;struct C;impl EntryCpuIo for C{fn read(&mut self,_:crate::stage14::EntryReg)->u64{0}fn write(&mut self,_:crate::stage14::EntryReg,_:u64){}fn clear_daif_a(&mut self){}fn isb(&mut self){}}struct M(u8);impl Mmio32 for M{fn read32(&mut self,_:u64)->u32{0}fn write32(&mut self,_:u64,_:u32){self.0+=1}}struct H(u8);impl EarlyClockReset for H{type Error=();fn prepare_clocks(&mut self)->Result<(),()>{self.0+=1;Ok(())}fn release_resets(&mut self)->Result<(),()>{self.0+=1;Ok(())}}#[test]fn startup(){let(mut c,mut m,mut h)=(C,M(0),H(0));run_early_startup(&mut c,&mut m,&mut h,8,24_000_000,0,&[EarlyPinOp::Pull{bank:0,pin:0,value:1}]).unwrap();assert_eq!(m.0,1);assert_eq!(h.0,2);}}
